import type { SortOrder } from '../types/data-item-types'
import type { WixDataQueryReferencedItemsOptions } from './types'

/**
 * Options builder for query referenced items operations.
 *
 * Use this builder to configure referenced item query behavior such as language,
 * selected fields, sort order and paging.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataQueryReferencedItemsOptionsBuilder {
  /**
   * Sets whether to include draft items in query results.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataQueryReferencedItemsOptionsBuilder
  /**
   * Sets app-specific query options.
   */
  withAppOptions(
    value: Record<string, any>
  ): WixDataQueryReferencedItemsOptionsBuilder
  /**
   * Sets the language used for the query.
   */
  withLanguage(value: string): WixDataQueryReferencedItemsOptionsBuilder
  /**
   * Sets whether the query uses consistent read mode.
   */
  withConsistentRead(value: boolean): WixDataQueryReferencedItemsOptionsBuilder
  /**
   * Sets whether to return the total result count with the query response.
   */
  withReturnTotalCount(
    value: boolean
  ): WixDataQueryReferencedItemsOptionsBuilder
  /**
   * Sets the fields returned for each referenced item.
   */
  withFields(...value: string[]): WixDataQueryReferencedItemsOptionsBuilder
  /**
   * Sets the sort order of the query results.
   */
  withOrder(value: SortOrder): WixDataQueryReferencedItemsOptionsBuilder
  /**
   * Sets offset-based paging options.
   */
  withPaging(value: {
    limit?: number
    offset?: number
  }): WixDataQueryReferencedItemsOptionsBuilder
  /**
   * Sets cursor-based paging options.
   */
  withCursorPaging(value: {
    cursor?: string
    limit?: number
  }): WixDataQueryReferencedItemsOptionsBuilder
  /**
   * Builds the query referenced items options object.
   */
  build(): WixDataQueryReferencedItemsOptions
}

class WixDataQueryReferencedItemsOptionsBuilderImpl
  implements WixDataQueryReferencedItemsOptionsBuilder
{
  constructor(
    private readonly options: WixDataQueryReferencedItemsOptions = {}
  ) {}

  withShowDrafts(value: boolean): WixDataQueryReferencedItemsOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withAppOptions(
    value: Record<string, any>
  ): WixDataQueryReferencedItemsOptionsBuilder {
    return this.copy({ appOptions: { ...value } })
  }

  withLanguage(value: string): WixDataQueryReferencedItemsOptionsBuilder {
    return this.copy({ language: value })
  }

  withConsistentRead(
    value: boolean
  ): WixDataQueryReferencedItemsOptionsBuilder {
    return this.copy({ consistentRead: value })
  }

  withReturnTotalCount(
    value: boolean
  ): WixDataQueryReferencedItemsOptionsBuilder {
    return this.copy({ returnTotalCount: value })
  }

  withFields(...value: string[]): WixDataQueryReferencedItemsOptionsBuilder {
    return this.copy({ fields: [...value] })
  }

  withOrder(value: SortOrder): WixDataQueryReferencedItemsOptionsBuilder {
    return this.copy({ order: value })
  }

  withPaging(value: {
    limit?: number
    offset?: number
  }): WixDataQueryReferencedItemsOptionsBuilder {
    return this.copy({ paging: { ...value } })
  }

  withCursorPaging(value: {
    cursor?: string
    limit?: number
  }): WixDataQueryReferencedItemsOptionsBuilder {
    return this.copy({ cursorPaging: { ...value } })
  }

  build(): WixDataQueryReferencedItemsOptions {
    return {
      ...this.options,
      ...(this.options.appOptions
        ? { appOptions: { ...this.options.appOptions } }
        : {}),
      ...(this.options.fields ? { fields: [...this.options.fields] } : {}),
      ...(this.options.paging ? { paging: { ...this.options.paging } } : {}),
      ...(this.options.cursorPaging
        ? { cursorPaging: { ...this.options.cursorPaging } }
        : {}),
    }
  }

  private copy(
    options: WixDataQueryReferencedItemsOptions
  ): WixDataQueryReferencedItemsOptionsBuilder {
    return new WixDataQueryReferencedItemsOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new query referenced items options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a query referenced items options builder"
 * import { items, QueryReferencedItemsOptionsBuilder } from '@wix/data'
 *
 * const options = QueryReferencedItemsOptionsBuilder()
 *   .withAppOptions({ key: 'value' })
 *   .withLanguage('en')
 *   .withConsistentRead(true)
 *   .withReturnTotalCount(true)
 *   .withFields('_id', 'title')
 *   .withOrder('ASC')
 *   .withPaging({ limit: 10, offset: 0 })
 *   .withCursorPaging({ cursor: 'eyJpZCI6IjEyMyJ9', limit: 10 })
 *   .build()
 *
 * const result = await items.queryReferencedItems<MyItem>(
 *   'myCollection',
 *   'myItemId',
 *   'relatedItems',
 *   options
 * )
 * ```
 */
export const QueryReferencedItemsOptionsBuilder: () => WixDataQueryReferencedItemsOptionsBuilder =
  () => new WixDataQueryReferencedItemsOptionsBuilderImpl()
